SELECT date_trunc('month',o.ordered_at AT TIME ZONE 'UTC')::DATE AS mon,p.category_id,sum(i.qty::DECIMAL(18,0)*i.unit_price)::DECIMAL(38,2) AS revenue FROM orders o JOIN order_items i USING(order_id) JOIN products p USING(product_id) WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00' AND i.qty*i.unit_price>=100.00 GROUP BY mon,p.category_id HAVING sum(i.qty::DECIMAL(18,0)*i.unit_price)>=100.00 ORDER BY mon,category_id;
